        C: { 文本: '先去找饮用水', 反抗等级: '微', 反抗消耗: 4,
             你会是什么样: '什么都不会发生。她大概会等你' },
        D: { 文本: '戴上项圈走到装置前', 反抗等级: '锁', 反抗消耗: 0,
             你会是什么样: '' }
      },
      她的倾向: '鼠标停在第二个上，又移开了',
      她已选: 'B',
      误点: false,
      她打的字: '',
      场面: {
        地点: '玻璃房',
        体位: '站着，从背后，她被压在镜面上，脸朝外',
        节奏: '很慢。每一下都停半拍，等她抖完了才继续',
        参与: {
          '莳羽梨香': { 在内: true,
            胸: '隔着校服顶起来两点，她用胳膊挡着，挡不住',
            阴部: '湿到腿上了，她自己还没承认',
            后穴: '还紧着，没碰过',
            反应: '膝盖一直在抖，站不太住' },
          '真中合欢': { 在内: false, 反应: '靠在门边，看着，没走' },
          '葵菜月': { 在内: false, 反应: '背过身去，手扶着洗面台' },
          '帆刈叶': { 在内: false, 反应: '站在门外，没进来' }
        },
        留痕: '玻璃上有一只手印，还没消',
        她看到的: '她把音量调小了'
      }
    }
  };

  function sd() {
    /* 从最新楼层往回找，用【负数深度索引】。
       依据 @types/function/variables.d.ts:17 ——
         「如果为负数则为深度索引，例如 -1 表示获取最新的消息楼层」
       不要用 getLastMessageId() + 正数楼层号：那个函数在 iframe 里不一定可用，
       拿不到就整个循环不执行，界面会静默退回 DEMO（表现就是「面板全是硬编码」）。
       负数索引不需要知道 chat.length，稳得多。
       超出 [-chat.length, chat.length) 会 throw，所以每层单独 try。 */
    for (var d = 1; d <= 40; d++) {
      try {
        var vv = getVariables({ type: 'message', message_id: -d });
        if (vv && vv.stat_data && vv.stat_data.主角) return vv.stat_data;
      } catch (e) { break; }
    }
    // 兜底一：界面自己所在楼层
    try {
      var v = getVariables({ type: 'message' });
      if (v && v.stat_data && v.stat_data.主角) return v.stat_data;
    } catch (e) {}
    // 兜底二：聊天级
    try {
      var c = getVariables({ type: 'chat' });
      if (c && c.stat_data && c.stat_data.主角) return c.stat_data;
    } catch (e3) {}
    return DEMO;
  }
  function pct(v) { return Math.max(0, Math.min(100, Number(v) || 0)) + '%'; }

  // 按 tavern-ui 规范：建消息 + /trigger 让 AI 铺开下一层
  // （不能用 /send，那样只发送不触发，下一层会没有正文）
  function send(text) {
    try {
      createChatMessages([{ role: 'user', name: '', message: text }]).then(function () {
        triggerSlash('/trigger');
      });
    } catch (e) {
      triggerSlash('/send ' + text);
    }
  }
  /* ── 判定引擎（E3 · 反抗判定）─────────────────────────
     算法出处：项目根的 机制.yaml → T2 状态表 → 反抗值（含成功率公式）
     LCG 确定性伪随机，禁 Math.random，保证同一回合重渲染结果一致
     ─────────────────────────────────────────────────────── */
  var LCG_A = 1664525, LCG_C = 1013904223, LCG_M = 4294967296;
  var 反抗基础 = { 微: 90, 中: 60, 强: 30, 极: 10, 自定义: 5 };
  var 反抗消耗表 = { 微: 4, 中: 12, 强: 30, 极: 55, 自定义: 70 };
  var 熟练罚 = { 新手: 0, 上手: 0.1, 沉浸: 0.2, 狂热: 0.3, 收官: 0.4 };

  function lcgNext(s) { return (LCG_A * s + LCG_C) % LCG_M; }

  /* 掷一次判定。两种走法共用这套骰子与公式：
     拒绝：对手是她点的那个选项，消耗按它的等级
     自己来：对手是她对局面的掌控，消耗固定 70、基础成功率 5
     反抗值由这里直接扣掉，不留给 AI 扣，免得两边重复扣。 */
  function rollAction(type, key, opt, text) {
    var d = sd(), m = d.主角 || {}, her = d.她 || {};
    var 等级 = type === '自定义' ? '自定义' : String((opt && opt.反抗等级) || '中');
    var 基础 = 反抗基础[等级];
    if (基础 === undefined) return null;
    var 消耗 = type === '自定义' ? 70 : (Number(opt && opt.反抗消耗) || 反抗消耗表[等级] || 0);
    var 现值 = Number(m.反抗值) || 0;
    if (现值 < 消耗) return { err: '要 ' + 消耗 + ' 点，你有 ' + 现值 + ' 点' };
    var 兴奋 = Number(her.兴奋度) || 0;
    var 罚 = 熟练罚[String(her.熟练度 || '新手')];
    if (罚 === undefined) 罚 = 0;
    var 率 = 基础 * (1 + 兴奋 / 100 * 0.5) * (1 - 罚);
    率 = Math.max(1, Math.min(99, 率));
    var 种子 = Number(m['$骰子种子']) || 20260914;
    var 新种子 = lcgNext(种子);
    var 掷 = (lcgNext(新种子) / LCG_M) * 100;
    var 成 = 掷 <= 率;
    var 差 = 率 - 50;
    var 档 = 成
      ? (差 >= 30 ? ['大成功', 1.5] : 差 >= 10 ? ['成功', 1.0] : ['勉强成功', 0.6])
      : (差 <= -30 ? ['大失败', 2.0] : ['失败', 1.0]);
    var 剩余 = Math.max(0, 现值 - 消耗);
    try {
      updateVariablesWith(function (v) {
        var cur = _.get(v, 'stat_data', {});
        _.set(v, 'stat_data', _.merge({}, cur, {
          主角: { '$骰子种子': 新种子, 反抗值: 剩余 },
          局面: {
            自定义意图: type === '自定义' ? String(text || '') : '',
            玩家拒绝: type === '拒绝' ? String(key) : '',
            判定结果: {
              操作: type,
              选项: type === '自定义' ? String(text || '') : String((opt && opt.文本) || ''),
              等级: 等级,
              消耗: 消耗,
              剩余反抗值: 剩余,
              成功率: Math.round(率 * 10) / 10,
              掷值: Math.round(掷 * 100) / 100,
              结果: 成 ? '成功' : '失败',
              档位: 档[0],
              效果倍数: 档[1]
            }
          }
        }));
        return v;
      }, { type: 'message', message_id: -1 });   // -1 = 最新楼层，AI 下一层能读到
    } catch (e) { console.log('[旮旯给木] 判定写回失败', e); }
    return { 率: 率, 掷: 掷, 成: 成, 档: 档[0], 消耗: 消耗, 剩余: 剩余 };
  }
  function two(n) { return (n < 10 ? '0' : '') + n; }
  var IDX = ['①', '②', '③', '④', '⑤', '⑥'];

  function clock() {
