#ggopen .og-sys{font-family:var(--fm);font-size:9.5px;letter-spacing:.34em;color:var(--ink4)}
#ggopen .og-sub{font-size:11.5px;letter-spacing:.14em;color:var(--ink3)}

#ggopen .og-lead{margin:0 0 14px;font-size:12.5px;line-height:1.9;color:var(--ink2)}

#ggopen .og-list{list-style:none;margin:0 0 13px;padding:0;display:flex;flex-direction:column;gap:7px}
#ggopen .og-opt{position:relative;display:flex;align-items:flex-start;gap:11px;
  padding:10px 13px;border-radius:3px;cursor:pointer;
  background:linear-gradient(100deg,rgba(233,230,223,.05),rgba(233,230,223,.02));
