#ggopen .og-opt:hover{transform:translateY(-1px);border-color:var(--herline);
  background:linear-gradient(100deg,var(--hersoft),rgba(233,230,223,.03))}
#ggopen .og-opt:hover::after{left:120%}

#ggopen .og-no{font-family:var(--fm);font-size:10.5px;letter-spacing:.08em;color:var(--ink4);
  flex:none;width:19px;padding-top:3px}
#ggopen .og-main{flex:1;min-width:0}
#ggopen .og-head{display:flex;align-items:baseline;gap:8px}
#ggopen .og-name{font-size:14px;color:var(--ink);letter-spacing:.02em}
#ggopen .og-tag{font-family:var(--fm);font-size:9.5px;letter-spacing:.14em;
