#ggopen .og-line{margin-top:3px;font-size:12.5px;color:var(--ink2);letter-spacing:.01em}
#ggopen .og-desc{margin-top:3px;font-size:11px;color:var(--ink4);line-height:1.6}
#ggopen .og-ck{flex:none;font-size:13px;color:var(--her);opacity:0;padding-top:2px;
  transition:opacity .18s ease}

#ggopen .og-opt:hover .og-name{color:var(--her)}
#ggopen .og-opt:hover .og-line{color:var(--ink)}
#ggopen .og-opt.chosen{border-color:var(--her);
  background:linear-gradient(100deg,rgba(223,174,95,.2),rgba(223,174,95,.05))}
#ggopen .og-opt.chosen .og-name{color:var(--her)}
#ggopen .og-opt.chosen .og-ck{opacity:1}
#ggopen .og-opt.chosen .og-tag{border-color:var(--herline);color:var(--her)}

#ggopen .og-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;
  padding-top:11px;border-top:1px solid var(--line)}
#ggopen .og-go{font-family:var(--f);font-size:12.5px;letter-spacing:.14em;
  padding:8px 20px;border-radius:3px;cursor:pointer;
  border:1px solid var(--herline);background:linear-gradient(180deg,rgba(223,174,95,.2),rgba(223,174,95,.06));
  color:var(--her);transition:.15s ease}
#ggopen .og-go:hover:not(:disabled){background:linear-gradient(180deg,rgba(223,174,95,.3),rgba(223,174,95,.12))}
#ggopen .og-go:disabled{border-color:var(--line);background:rgba(233,230,223,.03);
  color:var(--ink4);cursor:not-allowed}
#ggopen .og-note{font-family:var(--fm);font-size:10.5px;letter-spacing:.1em;color:var(--ink4)}

#ggopen .og-veil{position:absolute;inset:0;z-index:9;display:flex;flex-direction:column;
