<script>
(function () {
  var $ = function (id) { return document.getElementById(id); };

  // 7 套人设。选了谁就写进变量 她.人设，并把编号当标记发出去；
  // 世界书条目靠这个标记认人，开局正文由 AI 按「开局」条目铺开。
  // [id, 名字, 标签, 代表台词, 一句话说明]
  var ROSTER = [
    ['gentle',        '温砚', '救你',   '「你别怕，我在。」',       '她要带你活着出去。不会让你死'],
    ['greedy',        '丰娆', '看遍',   '「这个还没看过呢。」',     '把每个女角都看过一遍。重复的她会快进'],
    ['smirking',      '舒晏', '磨你',   '「求我啊。」',            '她要的是你挣扎。不理她比骂她更管用'],
    ['daredevil',     '唐响', '找极端', '「就这个，最狠的那个。」',  '找最极端的分支。平淡的日常她直接跳过'],
    ['quiet',         '沈眠', '推向死', '「……走这条路吧。」',      '把剧情推向死亡。她不接受圆满的收场'],
    ['indifferent',   '莫漾', '晾着',   '（她没说话）',            '她没有目的。手一离开鼠标，人就挂在那儿'],
    ['completionist', '纪清', '全收',   '「还差三格。」',          '全结局全 CG。为补一格能毁掉整条感情线']
    ,['feverish',     '郁燃', '自己要', '「就这个。」',            '她不是来看故事的。她自己要，不铺垫，直接上重的那一类']
  ];

  var picked = null;   // 选中的 id
  var locked = false;  // 提交后锁死

  function render() {
    $('og-list').innerHTML = ROSTER.map(function (r, i) {
      return '<li class="og-opt" role="button" tabindex="0" data-pid="' + r[0] + '" data-name="' + r[1] + '">' +
        '<span class="og-no">' + (i + 1 < 10 ? '0' : '') + (i + 1) + '</span>' +
        '<span class="og-main">' +
          '<span class="og-head">' +
            '<span class="og-name">' + r[1] + '</span>' +
            '<span class="og-tag">' + r[2] + '</span>' +
          '</span>' +
          '<span class="og-line">' + r[3] + '</span>' +
          '<span class="og-desc">' + r[4] + '</span>' +
        '</span>' +
        '<span class="og-ck">✓</span></li>';
    }).join('');
    Array.prototype.forEach.call($('og-list').querySelectorAll('.og-opt'), function (el) {
      el.onclick = function () { pick(el); };
      el.onkeydown = function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick(el); } };
    });
  }

  // 第一步：选。只是高亮，不提交
  function pick(el) {
    if (locked) return;
    picked = el.getAttribute('data-pid');
    var name = el.getAttribute('data-name');
    Array.prototype.forEach.call($('og-list').querySelectorAll('.og-opt'), function (x) {
      x.classList.toggle('chosen', x === el);
    });
    $('og-go').disabled = false;
    $('og-note').textContent = '已选：' + name;
  }

  // ── tavern-ui 规范：入口两道等待 ──
  // ① 等 MVU 框架初始化（window.Mvu 可用）
  // ② 等 MVU 脚本把 stat_data 写进这一楼的变量表
  // stat_data 由 MVU 脚本管理，不等就写入会落到尚未落表的空数据上。
  function whenReady(cb) {
    var tries = 0;
    (function poll() {
      var mvuReady = (typeof Mvu !== 'undefined');
      var sdReady = false;
      try {
        sdReady = _.has(getVariables({ type: 'message', message_id: getCurrentMessageId() }), 'stat_data');
      } catch (e) {}
      if ((mvuReady && sdReady) || tries >= 40) { cb(mvuReady, sdReady); return; }
      tries++;
      setTimeout(poll, 250);
    })();
  }

  // ── tavern-ui 规范写法 B：一次性命令式写入，手动合并 ──
  function writePersona(pid) {
    try {
      var option = { type: 'message', message_id: getCurrentMessageId() };
      updateVariablesWith(function (variables) {
        var cur = _.get(variables, 'stat_data', {});
        _.set(variables, 'stat_data', _.merge({}, cur, { 她: { 人设: pid } }));
        return variables;
      }, option);
      return true;
    } catch (e) {
      console.log('[旮旯给木] 写变量失败:', e);
      return false;
    }
  }

  // ── 跳到对应的那段开场白。依据 skills first-message.md:110：
  //    「表单本身即开局入口，选项决定被发送/触发的开场场景」
  //    所以选完必须做两件事：① 写变量 ② 切到对应的开场白。
  //    不是让 AI 现编一段。
  //
  //    本卡开场白的顺序：
  //      swipe 0 = first_mes（说明）
  //      swipe 1 = alternate_greetings[0]（表单本身）
  //      swipe 2 = [1] 温砚 ｜ 3 = [2] 丰娆 ｜ 4 = [3] 舒晏
  //      swipe 5 = [4] 唐响 ｜ 6 = [5] 沈眠 ｜ 7 = [6] 莫漾 ｜ 8 = [7] 纪清
  //    → swipe_id = 2 + ROSTER 里的序号 ──
  function submit(pid, name) {
    var 序 = 0;
    for (var i = 0; i < ROSTER.length; i++) { if (ROSTER[i][0] === pid) { 序 = i; break; } }
    var swipe_id = 2 + 序;
    try {
      if (typeof setChatMessages === 'function') {
        setChatMessages([{ message_id: 0, swipe_id: swipe_id }]).then(function () {
          $('og-veil-sub').textContent = '切到「' + name + '」的开局了。这一层就是';
        });
        return;
      }
      throw new Error('没有 setChatMessages');
    } catch (e) {
      // 兜底一：切不了 swipe，就发消息让 AI 按这套人设开始
      var payload = '[[GGPLAYER:' + pid + ']]\n选好了。这一局坐在屏幕前的是' + name + '。';
      try {
        createChatMessages([{ role: 'user', name: '', message: payload }]).then(function () {
          triggerSlash('/trigger');
        });
        $('og-veil-sub').textContent = '由她开第一局…';
      } catch (e2) {
        // 兜底二：都不行，提示手动切
        $('og-veil-sub').textContent = '变量已写入，但没能自动跳转。请手动把开场白切到「' + name + '」';
      }
    }
  }

  // 第二步：确认。到这里才写变量、才提交
  $('og-go').onclick = function () {
    if (locked || !picked) return;
    var el = $('og-list').querySelector('.og-opt.chosen');
    var name = el ? el.getAttribute('data-name') : '';
    locked = true;
    $('og-go').disabled = true;

    $('og-veil').hidden = false;
    $('og-veil-word').textContent = '她上线了';
    $('og-veil-sub').textContent = '正在接上这一局…';

    whenReady(function (mvuReady, sdReady) {
      var ok = writePersona(picked);
      console.log('[旮旯给木] Mvu=' + mvuReady + ' stat_data=' + sdReady + ' 写入=' + ok + ' 人设=' + picked);
      if (!ok) {
        locked = false;
        $('og-go').disabled = false;
        $('og-veil').hidden = true;
        $('og-note').textContent = '变量没写进去。刷新这一楼再选一次';
        return;
      }
      $('og-veil-sub').textContent = '这一局坐在屏幕前的是「' + name + '」';
      setTimeout(function () { submit(picked, name); }, 900);
    // 不锁死：用户滑回表单那一层还能重选（确认按钮由变量态控制）
    });
  };

  $(function () {
    try { render(); } catch (e) { render(); }
  });
})();
</script>
</body>
